CREATE TYPE "CustomerLifecycle" AS ENUM ('LEAD', 'PROSPECT', 'CUSTOMER', 'INACTIVE');
CREATE TYPE "CustomerInteractionType" AS ENUM ('CALL', 'EMAIL', 'MEETING', 'MESSAGE', 'NOTE');
ALTER TABLE "DepartmentMembership" ADD COLUMN "canViewCustomers" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "canManageCustomers" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Customer" ADD COLUMN "lifecycle" "CustomerLifecycle" NOT NULL DEFAULT 'LEAD', ADD COLUMN "source" TEXT, ADD COLUMN "ownerId" TEXT, ADD COLUMN "lastContactAt" TIMESTAMP(3), ADD COLUMN "nextFollowUpAt" TIMESTAMP(3);
CREATE TABLE "CustomerContact" ("id" TEXT NOT NULL, "customerId" TEXT NOT NULL, "name" TEXT NOT NULL, "role" TEXT, "phone" TEXT, "email" TEXT, "isPrimary" BOOLEAN NOT NULL DEFAULT false, "notes" TEXT, "metadata" JSONB NOT NULL DEFAULT '{}', "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CustomerContact_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CustomerInteraction" ("id" TEXT NOT NULL, "customerId" TEXT NOT NULL, "workCaseId" TEXT, "type" "CustomerInteractionType" NOT NULL, "happenedAt" TIMESTAMP(3) NOT NULL, "summary" TEXT NOT NULL, "outcome" TEXT, "nextFollowUpAt" TIMESTAMP(3), "metadata" JSONB NOT NULL DEFAULT '{}', "actorType" TEXT NOT NULL, "actorId" TEXT NOT NULL, "actorName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CustomerInteraction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CustomerAssignmentHistory" ("id" TEXT NOT NULL, "customerId" TEXT NOT NULL, "previousOwnerId" TEXT, "previousOwnerName" TEXT, "newOwnerId" TEXT, "newOwnerName" TEXT, "reason" TEXT, "actorType" TEXT NOT NULL, "actorId" TEXT NOT NULL, "actorName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CustomerAssignmentHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CustomerInteractionRevision" ("id" TEXT NOT NULL, "interactionId" TEXT NOT NULL, "previousData" JSONB NOT NULL, "actorType" TEXT NOT NULL, "actorId" TEXT NOT NULL, "actorName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CustomerInteractionRevision_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Customer_lifecycle_ownerId_idx" ON "Customer"("lifecycle", "ownerId");
CREATE INDEX "Customer_nextFollowUpAt_idx" ON "Customer"("nextFollowUpAt");
CREATE INDEX "CustomerContact_customerId_isPrimary_idx" ON "CustomerContact"("customerId", "isPrimary");
CREATE INDEX "CustomerInteraction_customerId_happenedAt_idx" ON "CustomerInteraction"("customerId", "happenedAt");
CREATE INDEX "CustomerInteraction_workCaseId_idx" ON "CustomerInteraction"("workCaseId");
CREATE INDEX "CustomerInteraction_nextFollowUpAt_idx" ON "CustomerInteraction"("nextFollowUpAt");
CREATE INDEX "CustomerAssignmentHistory_customerId_createdAt_idx" ON "CustomerAssignmentHistory"("customerId", "createdAt");
CREATE INDEX "CustomerInteractionRevision_interactionId_createdAt_idx" ON "CustomerInteractionRevision"("interactionId", "createdAt");
ALTER TABLE "Customer" ADD CONSTRAINT "Customer_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CustomerContact" ADD CONSTRAINT "CustomerContact_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CustomerInteraction" ADD CONSTRAINT "CustomerInteraction_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CustomerInteraction" ADD CONSTRAINT "CustomerInteraction_workCaseId_fkey" FOREIGN KEY ("workCaseId") REFERENCES "WorkCase"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CustomerAssignmentHistory" ADD CONSTRAINT "CustomerAssignmentHistory_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CustomerInteractionRevision" ADD CONSTRAINT "CustomerInteractionRevision_interactionId_fkey" FOREIGN KEY ("interactionId") REFERENCES "CustomerInteraction"("id") ON DELETE CASCADE ON UPDATE CASCADE;
